package hotel.messages;

import java.util.ArrayList;
import java.util.List;

public final class EmailProcessor {
    private final List<EmailRuleFactory> ruleFactories;

    public EmailProcessor(List<EmailRuleFactory> ruleFactories) {
        this.ruleFactories = ruleFactories;
    }

    public EmailMessage process(String to, String subject, String body) {
        List<String> messages = new ArrayList<>();
        String currentTo = to;
        String currentSubject = subject;
        String currentBody = body;
        String status = "SENT";

        for (EmailRuleFactory factory : ruleFactories) {
            EmailRuleResult result = factory.createRule().apply(currentTo, currentSubject, currentBody);
            if (result.isBlocked()) {
                status = "BLOCKED";
                currentTo = to;
                currentSubject = subject;
                currentBody = body;
                break;
            }
            currentTo = result.to();
